namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming education. PhD from MIT.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30 AM-12:00 PM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is a former Google engineer with research interests in algorithm optimization. PhD from Stanford.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS301", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", InstructorName = "Dr. Maria Patel", InstructorBio = "Dr. Patel has published extensively on distributed database systems. Previously at Oracle Research.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with 20 years of experience teaching undergraduate mathematics.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 1:00-2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on applied linear algebra and numerical methods.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 9:00-10:15 AM + Lab Fri 1:00-3:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist with research in condensed matter physics.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 7, DepartmentId = 3, CourseCode = "PHYS202", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park specializes in electromagnetic theory and has 10 years of teaching experience.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 8, DepartmentId = 4, CourseCode = "ENG101", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed 10:00-11:15 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing coach with expertise in academic writing.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 9, DepartmentId = 4, CourseCode = "ENG220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:30-3:45 PM", InstructorName = "Prof. Angela Brooks", InstructorBio = "Prof. Brooks specializes in 20th-century American fiction and has authored three critical studies.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST101", Title = "World History to 1500", Description = "Survey of world civilizations from ancient times through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a medievalist with archaeological fieldwork experience across Europe.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST205", Title = "Modern European History", Description = "Europe from the Renaissance through the 20th century, including political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:15 PM", InstructorName = "Dr. Catherine Shaw", InstructorBio = "Dr. Shaw is an expert in modern European political history with a focus on democratic movements.", IsFeatured = true, DepartmentName = "History" },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

