@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container mt-4">
    <div class="text-center mb-5">
        <h1 class="display-4">University Course Catalog</h1>
        <p class="lead text-muted">Explore our departments and courses for the upcoming semester.</p>
    </div>

    <section class="mb-5">
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-4 mb-3">
                    <div class="card h-100 border-primary">
                        <div class="card-body">
                            <h5 class="card-title">@course.Title</h5>
                            <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode &middot; @course.Credits credits</h6>
                            <p class="card-text">@course.Description[..Math.Min(100, course.Description.Length)]...</p>
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                        <div class="card-footer text-muted">
                            @course.DepartmentName
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mb-5">
        <h2 class="mb-3">Departments</h2>
        <div class="row">
            @foreach (var dept in _departments)
            {
                <div class="col-md-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text">@dept.Description</p>
                            <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">Browse Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <div class="text-center">
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
        <a href="/enroll" class="btn btn-success btn-lg ms-2">Enroll Now</a>
    </div>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@rendermode InteractiveServer
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Browse Courses</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="_searchTerm" @bind:event="oninput" @onkeyup="ApplyFilters" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="_selectedDepartmentId" @bind:after="ApplyFilters">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    @if (_courses.Count == 0)
    {
        <div class="alert alert-info">No courses found matching your criteria.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        <tr>
                            <td><strong>@course.CourseCode</strong></td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @_courses.Count course(s)</p>
    }
</div>

@code {
    private List<Department> _departments = new();
    private List<Course> _courses = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    [SupplyParameterFromQuery(Name = "departmentId")]
    public int? InitialDepartmentId { get; set; }

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        if (InitialDepartmentId.HasValue)
            _selectedDepartmentId = InitialDepartmentId.Value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        _courses = CatalogService.GetCourses(_searchTerm, deptFilter);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        ApplyFilters();
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted Successfully!</h4>
            <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for the selected course has been received. You will be contacted with confirmation details.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8">
                <div class="card">
                    <div class="card-body">
                        <p class="text-muted mb-4">Fill out the form below to submit an enrollment request. All fields are required.</p>

                        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollmentForm">
                            <DataAnnotationsValidator />
                            <ValidationSummary class="alert alert-danger" />

                            <div class="mb-3">
                                <label for="studentName" class="form-label">Full Name</label>
                                <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                                <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                            </div>

                            <div class="mb-3">
                                <label for="studentId" class="form-label">Student ID</label>
                                <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g., STU12345" />
                                <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                                <small class="form-text text-muted">6-10 uppercase alphanumeric characters</small>
                            </div>

                            <div class="mb-3">
                                <label for="courseSelect" class="form-label">Course</label>
                                <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                                    <option value="0">-- Select a course --</option>
                                    @foreach (var course in _courses)
                                    {
                                        <option value="@course.Id">@course.CourseCode - @course.Title (@course.Credits cr)</option>
                                    }
                                </InputSelect>
                                <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                            </div>

                            <button type="submit" class="btn btn-success btn-lg">Submit Enrollment Request</button>
                        </EditForm>
                    </div>
                </div>
            </div>

            <div class="col-md-4">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5>Need Help?</h5>
                        <p>Contact the Registrar's Office:</p>
                        <ul class="list-unstyled">
                            <li>📧 registrar&#64;university.edu</li>
                            <li>📞 (555) 123-4567</li>
                            <li>🏢 Admin Building, Room 101</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (PreselectedCourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = PreselectedCourseId.Value;
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(_model);
        if (success)
            _submitted = true;
    }
}

